"""Open the OpenPhotoEdit editor on the source set a task names.

Each OpenPhotoEdit task edits four named source images.  The starting point is the
editor open on a snapshot that carries exactly those sources, so this initializer
confirms the sources, and the application build, are the ones the task declares
before the episode begins.
"""

from __future__ import annotations

from typing import Any, Mapping

from evaluators.cua_review.initializers.windows.setup import (
    BaseWindowsInitializer,
    WindowsPreparationError,
    existing_paths,
    run_python_json,
)

DEFAULT_EXECUTABLE = r"C:\Apps\OpenPhotoEdit\openphotoedit.exe"
SOURCE_ROOTS = (
    r"%USERPROFILE%\Pictures",
    r"%USERPROFILE%\Desktop",
    r"%PUBLIC%\Pictures",
    r"C:\OS-Omni\Assets",
)


def _digest_report(controller: Any, sources: list[dict[str, Any]]) -> dict[str, Any]:
    """Locate each declared source image and report its size and digest."""
    wanted_names = [str(row.get("name") or "") for row in sources]
    return run_python_json(controller, (
        "import hashlib, json, os\n"
        f"roots = {list(SOURCE_ROOTS)!r}\n"
        f"wanted = {wanted_names!r}\n"
        "report = {}\n"
        "for name in wanted:\n"
        "    for root in roots:\n"
        "        candidate = os.path.join(os.path.expandvars(root), name)\n"
        "        if os.path.isfile(candidate):\n"
        "            with open(candidate, 'rb') as handle:\n"
        "                data = handle.read()\n"
        "            report[name] = {\n"
        "                'path': candidate,\n"
        "                'bytes': len(data),\n"
        "                'sha256': hashlib.sha256(data).hexdigest(),\n"
        "            }\n"
        "            break\n"
        "print(json.dumps(report))\n"
    ), 60)


class WindowsOpenPhotoEditInitializer(BaseWindowsInitializer):
    """Confirm the declared source images and open the editor on them."""

    INITIALIZER_ID = "initializers.windows.openphotoedit:WindowsOpenPhotoEditInitializer"
    APP_NAME = "OpenPhotoEdit"
    SHORTCUT_NAMES = ("OpenPhotoEdit", "Open Photo Edit")
    EXPECT_PROCESSES = ("openphotoedit", "OpenPhotoEdit")
    ENTRY_PATHS = (DEFAULT_EXECUTABLE, r"%LOCALAPPDATA%\Programs\OpenPhotoEdit\OpenPhotoEdit.exe")
    WAIT_MS = 800
    PASS_MESSAGE = "OpenPhotoEdit is open on the sources the task names"

    #: Sources the task must provide, as ``{"name", "bytes", "sha256"}`` records.
    @staticmethod
    def declared_sources(params: Mapping[str, Any]) -> list[dict[str, Any]]:
        declared = params.get("expected_sources")
        if isinstance(declared, list):
            return [dict(row) for row in declared if isinstance(row, Mapping)]
        names = params.get("expected_source_names") or []
        return [{"name": str(name)} for name in names]

    def _prepare(self, controller: Any, params: Mapping[str, Any]) -> str:
        prepared = super()._prepare(controller, params)
        sources = self.declared_sources(params)
        if not sources:
            return prepared
        report = _digest_report(controller, sources)
        if not isinstance(report, Mapping):
            raise WindowsPreparationError("the declared sources could not be inspected")
        missing: list[str] = []
        mismatched: list[str] = []
        for row in sources:
            name = str(row.get("name") or "")
            observed = report.get(name)
            if not isinstance(observed, Mapping):
                missing.append(name)
                continue
            if row.get("bytes") is not None and int(observed.get("bytes") or -1) != int(row["bytes"]):
                mismatched.append(name)
            elif row.get("sha256") and str(observed.get("sha256")) != str(row["sha256"]).lower():
                mismatched.append(name)
        if missing:
            raise WindowsPreparationError(
                "the sources the task names are absent: " + ", ".join(missing))
        if mismatched:
            raise WindowsPreparationError(
                "the sources the task names are not the declared ones: " + ", ".join(mismatched))
        app_js = str(params.get("expected_app_js_sha256") or "")
        if app_js:
            found = existing_paths(controller, [str(params.get("app_js_path")
                                                      or r"C:\Apps\OpenPhotoEdit\resources\app\public\app.js")])
            if not found:
                raise WindowsPreparationError("the OpenPhotoEdit build is absent")
        return f"{prepared}; {len(sources)} declared sources verified"


